				case staticAuthNamespaced:
					config.name = fmt.Sprintf("%s with static auth namespaced token", config.name)
				case jwtAuth:
					config.name = fmt.Sprintf("%s with jwt auth", config.name)
				case k8sAuth:
					config.name = fmt.Sprintf("%s with k8s auth", config.name)
