func cacheTLS(ctx context.Context, client *dagger.Client, base, flipt *dagger.Container, conf testConfig) func() error {
	caCert, serverCert, serverKey, err := redisTLSCertificates()
	if err != nil {
		return func() error { return err }
	}

	redis := client.Container().
		From("redis:alpine").
		WithNewFile("/tls/ca.crt", dagger.ContainerWithNewFileOpts{Contents: caCert}).
		WithNewFile("/tls/server.crt", dagger.ContainerWithNewFileOpts{Contents: serverCert}).
		WithNewFile("/tls/server.key", dagger.ContainerWithNewFileOpts{Contents: serverKey}).
		WithExposedPort(6379).
		WithExec([]string{
			"redis-server", "--port", "0", "--tls-port", "6379",
			"--tls-cert-file", "/tls/server.crt", "--tls-key-file", "/tls/server.key",
			"--tls-ca-cert-file", "/tls/ca.crt", "--tls-auth-clients", "no",
		}).
		AsService()

	flipt = flipt.
		WithServiceBinding("redis", redis).
		WithNewFile("/etc/flipt/redis-ca.crt", dagger.ContainerWithNewFileOpts{Contents: caCert}).
		WithEnvVariable("FLIPT_CACHE_ENABLED", "true").
		WithEnvVariable("FLIPT_CACHE_BACKEND", "redis").
		WithEnvVariable("FLIPT_CACHE_REDIS_HOST", "redis").
		WithEnvVariable("FLIPT_CACHE_REDIS_PORT", "6379").
		WithEnvVariable("FLIPT_CACHE_REDIS_REQUIRE_TLS", "true").
		WithEnvVariable("FLIPT_CACHE_REDIS_CA_CERT_PATH", "/etc/flipt/redis-ca.crt")

	return suite(ctx, "api", base, flipt.WithExec(nil), conf)
}

func redisTLSCertificates() (caCert, serverCert, serverKey string, err error) {
	caKey, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		return "", "", "", err
	}

	serverPrivateKey, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		return "", "", "", err
	}

	now := time.Now()
	ca := &x509.Certificate{
		SerialNumber:          big.NewInt(1),
		Subject:               pkix.Name{CommonName: "Flipt Redis integration CA"},
		NotBefore:             now.Add(-time.Hour),
		NotAfter:              now.Add(24 * time.Hour),
		IsCA:                  true,
		KeyUsage:              x509.KeyUsageCertSign,
		BasicConstraintsValid: true,
	}

	caDER, err := x509.CreateCertificate(rand.Reader, ca, ca, &caKey.PublicKey, caKey)
	if err != nil {
		return "", "", "", err
	}

	server := &x509.Certificate{
		SerialNumber: big.NewInt(2),
		Subject:      pkix.Name{CommonName: "redis"},
		DNSNames:     []string{"redis"},
		NotBefore:    now.Add(-time.Hour),
		NotAfter:     now.Add(24 * time.Hour),
		KeyUsage:     x509.KeyUsageDigitalSignature,
		ExtKeyUsage:  []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth},
	}

	serverDER, err := x509.CreateCertificate(rand.Reader, server, ca, &serverPrivateKey.PublicKey, caKey)
	if err != nil {
		return "", "", "", err
	}

	keyDER, err := x509.MarshalECPrivateKey(serverPrivateKey)
	if err != nil {
		return "", "", "", err
	}

	return string(pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: caDER})),
		string(pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: serverDER})),
		string(pem.EncodeToMemory(&pem.Block{Type: "EC PRIVATE KEY", Bytes: keyDER})), nil
}

